package com.yeyamo_mobile.api.recommendation_service.application;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.recommendation_service.application.port.*;import com.yeyamo_mobile.api.recommendation_service.application.scoring.*;import com.yeyamo_mobile.api.recommendation_service.domain.*;
@Service public class RecommendationQueryService{private final RecommendationProjectionPort projections;private final RecommendationCachePort cache;private final RecommendationOutboxPort outbox;private final List<ScoringStrategy>strategies;private final ScoringProperties weights;@Autowired public RecommendationQueryService(RecommendationProjectionPort p,RecommendationCachePort c,RecommendationOutboxPort o,List<ScoringStrategy>s,ScoringProperties w){projections=p;cache=c;outbox=o;strategies=List.copyOf(s);weights=w;}public RecommendationQueryService(RecommendationProjectionPort p,RecommendationCachePort c,RecommendationOutboxPort o,List<ScoringStrategy>s){this(p,c,o,s,new ScoringProperties());}@Transactional public RecommendationPage recommend(String user,RecommendationContext context,int page,int size,String correlation){int p=Math.max(0,page),s=Math.max(1,Math.min(50,size));return cache.get(user,context,p,s).orElseGet(()->generate(user,context,p,s,correlation));}private RecommendationPage generate(String user,RecommendationContext context,int page,int size,String correlation){RecommendationProfile profile=projections.profile(user);List<RecommendationItem>ranked=projections.activeCandidates(500).stream().map(c->item(c,profile,context)).sorted(Comparator.comparingDouble((RecommendationItem i)->i.score().total()).reversed().thenComparing(RecommendationItem::targetId)).toList();long offset=(long)page*size;int from=(int)Math.min(offset,ranked.size()),to=Math.min(from+size,ranked.size());RecommendationPage result=new RecommendationPage(page,size,to<ranked.size(),List.copyOf(ranked.subList(from,to)),Instant.now());cache.put(user,context,page,size,result);outbox.append("recommendation.generated",user,correlation,Map.of("userId",user,"count",result.items().size(),"page",page,"scoringVersion",1));return result;}private RecommendationItem item(Candidate c,RecommendationProfile p,RecommendationContext x){Map<String,Double>parts=new LinkedHashMap<>();strategies.forEach(strategy->parts.put(strategy.name(),round(strategy.score(c,p,x)*weights.weight(strategy.name()))));double total=round(parts.values().stream().mapToDouble(Double::doubleValue).sum());return new RecommendationItem(c.targetId(),c.kind(),c.title(),c.categoryCode(),c.regionCode(),c.latitude(),c.longitude(),new RecommendationScore(total,parts));}private double round(double value){return Math.round(value*100d)/100d;}}
